#!/usr/bin/env bash
# job 3, older entries: one snap.sh call at a time
set -u
S=/home/claude/theseus/feedback/snap.sh
O=/home/claude/work/fa/old
V3='The player opened in 3D by default then (2D if he had switched, remembered by his browser); the 3D assets on disk today are not that day'"'"'s, so these are the 2D view.'
run() { echo "=== $(date +%H:%M:%S) $*"; nice -n 10 "$S" "$@" || echo "FAILED $*"; }
WHEN='2026-11-05 ~06:30' LIVE='v22 (published 06:01)' COMMIT='990a95c' BUILD='the published page, git show 990a95c:deck/dist/main.html' NOTE="F31: the slides K1's questions were about (Razer's half on clk_switch, Direct Drive's 6 % on arc, the pads on anchors, the guide over the full-size switch on sidebuttons). $V3" run F31 $O/v22.html clk_switch:settle arc:settle anchors:settle sidebuttons:settle
WHEN='2026-11-05 ~05:22' LIVE='v21 (published 05:09; no page committed) or v20 (04:07)' COMMIT='305acc1 (v20; v21, 5fdc7b1, changed only how ratings archive)' BUILD='the published v20 page, git show 305acc1:deck/dist/main.html' NOTE="F30.8: the wheel with the diamond knurl he turned down (\"i liked the scroll wheel version with lines better\"). $V3" run F30 $O/v20.html wheel:settle
WHEN='2026-11-05 01:43' LIVE='v19 (published 01:28)' COMMIT='6ec4864' BUILD='the published page, git show 6ec4864:deck/dist/main.html' NOTE="F26.10: frame sync as it was (his 42 µs for the XA25, 202 µs for the Viper V4 Pro). The other slides F26 and F25 name are in frames/F27/ (same build). $V3" run F26 $O/v19.html framesync:settle
WHEN='2026-11-04 ~23:00' LIVE='v16 (published 22:50)' COMMIT='cf7cacd' BUILD='the published page, git show cf7cacd:deck/dist/main.html' NOTE="F22: the wheel he called bulky, the Mars base dome slide he cut, frame sync, and the budget the screws and wires went into. $V3" run F22 $O/v16.html wheel:settle shbDome:settle framesync:settle budget:settle
WHEN='2026-11-04 10:30' LIVE='not recorded; nearest committed build before: 42cf92c (10:10)' COMMIT='42cf92c' BUILD='git show 42cf92c:deck/dist/main.html' NOTE="F16.1: arc's count down to zero (he sent a screenshot of it, not kept), mid and settle. $V3" run F16 $O/c1010.html arc:mid,settle
WHEN='2026-11-04 10:17' LIVE='not recorded; nearest committed build before: 42cf92c (10:10)' COMMIT='42cf92c' BUILD='git show 42cf92c:deck/dist/main.html' NOTE="F14: the GT01 on the clicks card (F14.3), the dots before the pills (F14.1), the mousepad image (F14.4), the fallacy slide and the question alone on its next slide's first frame (F14.5), the slide he retitled (F14.7). $V3" run F14 $O/c1010.html clicks:settle gld_under:settle gld_camera:settle shlPick:settle shlNoPick:first,settle shlWork:settle
WHEN='2026-11-04 09:28' LIVE='not recorded; nearest committed build before: 427363c (08:47)' COMMIT='427363c' BUILD='git show 427363c:deck/dist/main.html' NOTE="F12.9: the notch in the rear trigger cutouts; F12.10: the optional base with big holes. $V3" run F12 $O/c0847.html cutouts:settle shlsheet2:settle
WHEN='2026-11-04 07:20' LIVE='not recorded; nearest committed build before: 8293736 (04:45, also the build behind F7 at 04:52)' COMMIT='8293736' BUILD='git show 8293736:deck/dist/main.html' NOTE="F9: the cover (F9.11), magnetic clicks (F9.9), the radio module (F9.13), the GT01 (F9.15), the side buttons (F9.16), the encoder (F9.21), zero grams (F9.26), an unfilleted lattice (F9.27); the same build shows F7's look. $V3" run F9 $O/c0445.html cover:settle magbuttons:settle antenna:settle clicks:settle sidebuttons:settle sealed:settle zerograms:settle lattice:settle
